create schema sc;

CREATE TABLE SC.LAB ( LAB_ID NUMBER(4) NOT NULL, LAB_NAME VARCHAR2(50) NOT NULL, LAB_ADDRESS VARCHAR2(255), LAB_COUNTRY VARCHAR2(2), CONSTRAINT LAB_PK PRIMARY KEY (LAB_ID) );

CREATE TABLE SC.ORIG_SYSTEM ( SYSTEM_ID NUMBER(3) NOT NULL, SYSTEM_CODE VARCHAR2(8) NOT NULL, COORD_SYSTEM VARCHAR2(64) NOT NULL, TYPE VARCHAR2(6) NOT NULL, ALLOWED_UNIT VARCHAR2(5), HUMAN_NAME VARCHAR2(100), PRIMARY KEY (SYSTEM_ID) );
COMMENT ON TABLE SC.ORIG_SYSTEM IS 'Original system used prior to conversion to LAT/LONG';

CREATE TABLE SC.METHOD ( METHOD_ID NUMBER(3) NOT NULL, METHOD VARCHAR2(64) NOT NULL, NOM_ACCURACY_XY NUMBER(10,2), NOM_ACCURACY_Z NUMBER(10,2), PRIMARY KEY (METHOD_ID) );



























